int32_t last_level_payload;

bool get_level(int32_t *data) {
  sb_event_counter_t numDropped;
  int32_t fresh_data;
  bool isFresh = sb_queue_int32_t_1_dequeue((sb_queue_int32_t_1_Recv_t *) &level_recv_queue, &numDropped, &fresh_data);
  if (isFresh) {
    last_level_payload = fresh_data;
  }
  *data = last_level_payload;
  return isFresh;
}

bool peek_level(int32_t *data) {
  sb_event_counter_t numDropped;
  int32_t freshData;
  bool isFresh = sb_queue_int32_t_1_peek((sb_queue_int32_t_1_Recv_t *) &level_recv_queue, &numDropped, &freshData);
  *data = isFresh ? freshData : last_level_payload;
  return isFresh;
}

